SELECT DISTINCT a.* from ( SELECT DISTINCT a.industry_code, a.app_ver_code, b.tenant_id FROM vm_order_package b LEFT JOIN sys_industry_ver_conf a ON a.industry_code = b.industry_code AND a.app_ver_code = b.app_ver_code LEFT JOIN sys_industry_conf f ON a.industry_code = f.industry_code and f.delete_flag = 0 WHERE a.delete_flag = 0 and a.accept_node = #{platformCode} and f.accept_node = #{platformCode}
UNION
SELECT DISTINCT a.industry_code, a.app_ver_code, c.tenant_id FROM vm_order_package_his c LEFT JOIN sys_industry_ver_conf a ON a.industry_code = c.industry_code AND a.app_ver_code = c.app_ver_code LEFT JOIN sys_industry_conf f ON a.industry_code = f.industry_code and f.delete_flag = 0 WHERE a.delete_flag = 0 and a.accept_node = #{platformCode} and f.accept_node = #{platformCode} ) a

